"""matplotlib._api — internal API utilities."""

import warnings

def warn_deprecated(since, *, message='', name='', alternative='',
                    pending=False, obj_type='', addendum='', removal=''):
    warnings.warn(f'{name} is deprecated since {since}', DeprecationWarning, stacklevel=2)

def check_isinstance(_types, **kwargs):
    for k, v in kwargs.items():
        if not isinstance(v, _types):
            raise TypeError(f'{k} must be {_types}, got {type(v)}')

def check_in_list(_values, **kwargs):
    for k, v in kwargs.items():
        if v not in _values:
            raise ValueError(f'{v!r} is not in {_values}')

def check_shape(_shape, **kwargs):
    """Validate that every array kwarg matches ``_shape``. ``_shape`` is
    a tuple where ``None`` means "any size in this dimension". Raises
    :class:`ValueError` on mismatch.

    Mirrors upstream's :func:`matplotlib._api.check_shape` signature.
    """
    import numpy as _np
    for name, arr in kwargs.items():
        actual = _np.shape(arr) if not hasattr(arr, 'shape') else arr.shape
        if len(actual) != len(_shape):
            raise ValueError(
                f'{name!r} must have shape {_shape}, but has shape {actual}')
        for a, e in zip(actual, _shape):
            if e is not None and a != e:
                raise ValueError(
                    f'{name!r} must have shape {_shape}, but has shape {actual}')


def check_getitem(_mapping, **kwargs):
    """Validate that each kwarg is a key in ``_mapping``. Returns the
    value for the first kwarg (mirrors upstream — only one kwarg is
    typically passed, this is sugar for "validate + lookup")."""
    for k, v in kwargs.items():
        if v not in _mapping:
            raise ValueError(
                f'{v!r} is not a valid value for {k}; '
                f'supported values are {sorted(_mapping)}')
        return _mapping[v]

def classproperty(func):
    return property(func)

def delete_parameter(since, name, func=None, **kwargs):
    if func is None:
        return lambda f: f
    return func

def make_keyword_only(since, name, func=None):
    if func is None:
        return lambda f: f
    return func

def rename_parameter(since, old, new, func=None):
    if func is None:
        return lambda f: f
    return func

class deprecation:
    @staticmethod
    def deprecated(since, **kwargs):
        def decorator(obj):
            return obj
        return decorator


