def warn_external(message, category=None):
    """Issue a warning that should appear to originate from the caller's
    code, not from matplotlib internals. Upstream walks the stack to
    find a frame outside matplotlib; we just emit a regular warning."""
    import warnings
    warnings.warn(message, category or UserWarning, stacklevel=3)


def caching_module_getattr(cls):
    """Class decorator that turns a class with ``@property`` attributes
    into a module-level ``__getattr__``, caching results. Used by
    upstream's ``cm.py`` etc. We mimic the behaviour with a simple
    cached-property lookup wrapper."""

    def _getattr(name, _cache={}, _cls=cls):
        if name in _cache:
            return _cache[name]
        prop = getattr(_cls, name, None)
        if isinstance(prop, property):
            val = prop.fget(_cls)
            _cache[name] = val
            return val
        raise AttributeError(name)

    return _getattr


def define_aliases(alias_d, cls=None):
    """Decorator that installs ``get_<long_name>`` / ``set_<long_name>``
    aliases on ``cls``. ``alias_d`` maps the canonical name to a list
    of aliases. The shim wires the aliases up by forwarding."""

    def _apply(target_cls):
        for canonical, aliases in alias_d.items():
            for alias in aliases:
                # Set up get/set aliases that forward to the canonical name.
                if hasattr(target_cls, f'get_{canonical}'):
                    setattr(target_cls, f'get_{alias}',
                            getattr(target_cls, f'get_{canonical}'))
                if hasattr(target_cls, f'set_{canonical}'):
                    setattr(target_cls, f'set_{alias}',
                            getattr(target_cls, f'set_{canonical}'))
        return target_cls

    if cls is not None:
        return _apply(cls)
    return _apply


def kwarg_error(name, kw):
    """Raise the standard "unexpected keyword argument" TypeError
    matching CPython's wording."""
    return TypeError(f"{name}() got an unexpected keyword argument {next(iter(kw))!r}")


def nargs_error(name, takes, given):
    """Raise the standard "wrong number of positional arguments"
    TypeError."""
    return TypeError(
        f"{name}() takes {takes} positional arguments but {given} were given")


def recursive_subclasses(cls):
    """Yield every direct and transitive subclass of ``cls``."""
    seen = set()
    stack = [cls]
    while stack:
        c = stack.pop()
        for sub in c.__subclasses__():
            if sub not in seen:
                seen.add(sub)
                yield sub
                stack.append(sub)


def select_matching_signature(funcs, *args, **kwargs):
    """Try calling each function in ``funcs`` and return the first
    successful result. Used by upstream to dispatch overloaded APIs.
    """
    last_err = None
    for fn in funcs:
        try:
            return fn(*args, **kwargs)
        except TypeError as e:
            last_err = e
    if last_err is not None:
        raise last_err
    raise TypeError("no matching signature")
